function iso(minutes: number): string { return new Date(Date.parse(at) + minutes * 60_000).toISOString(); }
function candle(minutes: number, open: number, high: number, low: number, close: number): MarketPriceCandle { return { timestamp: iso(minutes), open, high, low, close, volume: 1000 }; }
function priceCandles(status: MarketGoldenScenarioPriceReactionExpectation['expectedStatus']): MarketPriceCandle[] {
  const pre = [candle(-3, 100, 100.2, 99.8, 100), candle(-2, 100, 100.2, 99.8, 100), candle(-1, 100, 100.2, 99.8, 100)];
  if (status === 'confirmed') return [...pre, candle(0, 100, 101.4, 99.9, 101.2), candle(1, 101.2, 101.8, 101, 101.6), candle(2, 101.6, 102, 101.4, 101.9), candle(3, 101.9, 102.3, 101.7, 102.1)];
  if (status === 'rejected') return [...pre, candle(0, 100, 100.1, 98.4, 98.7), candle(1, 98.7, 99, 98.2, 98.4), candle(2, 98.4, 98.7, 98, 98.2), candle(3, 98.2, 98.4, 97.8, 98)];
  if (status === 'absorbed') return [...pre, candle(0, 100, 100.8, 99.2, 100.02), candle(1, 100.02, 100.7, 99.3, 100.01), candle(2, 100.01, 100.6, 99.4, 100.02), candle(3, 100.02, 100.5, 99.5, 100.01)];
  if (status === 'reversed') return [...pre, candle(0, 100, 101.3, 99.9, 101.1), candle(1, 101.1, 101.2, 99.3, 99.5), candle(2, 99.5, 99.6, 98.6, 98.9), candle(3, 98.9, 99, 98.2, 98.4)];
  return [];
}

